/**
 * Mirrors the shape of hono/client's shipped declarations — the package whose type-only
 * answer killed mx5 run 15. What matters for the F-2 regression test is structural, not
 * cosmetic:
 *
 *   1. `hc`'s parameters are named only by OPAQUE TYPE VARIABLES (`baseUrl: Prefix`). The
 *      declaration is complete and correct and still cannot say whether `baseUrl` is an
 *      ORIGIN or a MOUNT PREFIX — the exact semantic gap the worker filled from memory.
 *   2. The semantics live behind a `@see {@link …}` JSDoc pointer, in the very text the
 *      docs worker retrieves. F-2(d): in run 15, hono.dev appeared in cache values ONLY
 *      inside links like this one, and was never fetched.
 *
 * The version is pinned to 4.12.31, the range mx5 declared, so the fixture reads as the
 * real case rather than a toy.
 */

export declare class Hono<E = unknown, S = unknown, P extends string = '/'> {
    routes: unknown[]
}

export interface ClientRequestOptions {
    headers?: Record<string, string>
    fetch?: typeof fetch
    init?: RequestInit
}

export type Client<T, P> = {[K in keyof T]: T[K]}

export type UnionToIntersection<U> = (U extends unknown ? (k: U) => void : never) extends (
    k: infer I
) => void ?
    I
:   never

/**
 * Creates a typed RPC client for a Hono app.
 *
 * @see {@link https://hono.dev/docs/guides/rpc}
 */
export declare const hc: <T extends Hono, Prefix extends string = string>(
    baseUrl: Prefix,
    options?: ClientRequestOptions
) => UnionToIntersection<Client<T, Prefix>>
